-- Черновики цитат и фильмов для утверждения заказчиком. Все НЕ проверены (verified = false), ученикам не показываются,
-- пока заказчик не сверит источник и не отметит «проверена» в админке (Контент → Цитаты / Фильмы)
insert into quotes (text, author, source, verified, tags)
select * from (values
  ('Пока мы откладываем, жизнь проходит', 'Сенека', 'Нравственные письма к Луцилию, письмо 1', false, '{no_actions_3d}'::text[]),
  ('То, что стоит на пути, становится путём', 'Марк Аврелий', 'Размышления, 5.20', false, '{no_checkpoint}'::text[]),
  ('Любишь жизнь? Тогда не трать время впустую: из него она сделана', 'Бенджамин Франклин', 'Альманах бедного Ричарда', false, '{}'::text[]),
  ('Путь в тысячу ли начинается с первого шага', 'Лао-цзы', 'Дао дэ цзин, 64', false, '{no_actions_3d}'::text[]),
  ('Лучшее — враг хорошего', 'Вольтер', 'Безрассудная, 1772', false, '{homework_overdue}'::text[]),
  ('Сначала скажи себе, кем хочешь быть, затем делай то, что для этого нужно', 'Эпиктет', 'Беседы, 3.23', false, '{perspective_gap}'::text[]),
  ('Лови день, не доверяя будущему', 'Гораций', 'Оды, 1.11', false, '{}'::text[]),
  ('Великие дела делаются не силой, а упорством', 'Сэмюэл Джонсон', 'Расселас, 1759', false, '{stuck_lesson}'::text[])
) v(text, author, source, verified, tags)
where not exists (select 1 from quotes q where q.text = v.text);

insert into movies (title, year, why, tags, verified)
select * from (values
  ('Одержимость', 2014, 'Про цену мастерства: как ежедневная практика превращает талант в результат. Подходит, когда не хочется браться за урок', '{stuck_lesson,lessons_skipped,no_actions_3d}'::text[], false),
  ('Рататуй', 2007, 'Про ремесло и смелость показать своё дело людям. Подходит, когда сомневаешься, стоит ли выкладывать видео', '{video_zero_direction,insights_none}'::text[], false),
  ('Повар на колёсах', 2014, 'Мастер возвращается к любимому делу и растёт через соцсети. Подходит, когда нужны клиенты из контента', '{video_zero_direction,video_views_low}'::text[], false),
  ('Человек, который изменил всё', 2011, 'Про решения по цифрам вместо ощущений. Подходит, когда замер откладывается или цифры стоят на месте', '{no_checkpoint,metric_flat,metric_dropped}'::text[], false),
  ('Рокки', 1976, 'Про упорство и работу над собой без гарантий. Подходит, когда нет сил сделать даже маленький шаг', '{no_actions_3d,homework_overdue}'::text[], false),
  ('В погоне за счастьем', 2006, 'Про стойкость в тяжёлое время. Подходит, когда результат пока не виден', '{metric_dropped,booking_low}'::text[], false),
  ('Ford против Ferrari', 2019, 'Про перфекционизм и работу на результат. Подходит, когда пройдено много, а до клиентов не доходит', '{perspective_gap,ahead_plan}'::text[], false),
  ('Дзиро мечтает о суши', 2011, 'Про мастера, который всю жизнь улучшает одно дело. Подходит, когда хочется бросить на полпути', '{stuck_lesson,lessons_skipped}'::text[], false),
  ('Основатель', 2016, 'Про систему, рост и масштаб одного дела. Подходит, когда пора поднимать цену и выстраивать запись', '{price_flat,booking_low}'::text[], false),
  ('Парикмахерская', 2002, 'Комедия про барбершоп и его хозяина. Подходит, когда нужна лёгкая перезагрузка после тяжёлой недели', '{booking_low,price_flat}'::text[], false)
) v(title, year, why, tags, verified)
where not exists (select 1 from movies m where m.title = v.title);
